P.CR = {"crTitle":"Cùng đọc","crCopyB":"Sao chép liên kết","crTile_d":"Dẫn dắt hoặc tham gia: điện thoại của mọi người cùng theo một chương, một câu","crHostB":"Tôi sẽ dẫn đọc","crHostD":"Điện thoại của mọi người sẽ theo tôi đến cùng một chương, cùng vị trí cuộn, câu tôi chạm vào và chỗ đang đọc to","crJoinB":"Tham gia","crJoinD":"Nhập mã 6 ký tự của người dẫn đọc (hoặc chạm vào liên kết họ gửi, hoặc quét mã QR)","crCodePh":"Mã 6 ký tự","crJoinGo":"Tham gia","crNamePh":"Tên của bạn (để người dẫn đọc biết bạn đã đến)","crBadCode":"Xin nhập mã 6 ký tự","crStarting":"Đang bắt đầu Cùng đọc…","crJoining":"Đang tham gia…","crCode":"Mã","crScan":"Hãy nhờ họ quét mã QR bằng máy ảnh điện thoại, hoặc chạm vào 📡 trên trang đọc rồi nhập mã","crShareLink":"Gửi liên kết mời","crInviteMsg":"Mời bạn cùng đọc với tôi trong 321 Kinh Thánh Tương Tác. Hãy chạm vào liên kết bên dưới để tham gia (mã {0}):","crMembers":"{0} người đã tham gia","crNone":"Chưa có ai tham gia — hãy chia sẻ liên kết hoặc mã QR","crEnd":"Kết thúc","crLeaveB":"Rời đi","crInv":"Mời","crHostBar":"Đang dẫn đọc {0}","crGuestBar":"Đang theo {0}","crWait":"Đang kết nối…","crOff":"không ở trang đọc","crFollow":"Quay lại với người dẫn đọc","crFree":"Tự xem riêng","crFollowB":"Tự xem riêng","crFreeB":"Quay lại với người dẫn đọc","crFollowOn":"Đang theo người dẫn đọc","crFreeOn":"Bạn có thể tự do xem riêng — chạm “Quay lại với người dẫn đọc” để theo lại","crJoined":"{0} đã tham gia","crLeft":"{0} đã rời đi","crEnded":"Người dẫn đọc đã kết thúc buổi Cùng đọc. Nguyện Chúa ban phước cho bạn!","crNoRoom":"Không tìm thấy buổi đọc này. Hãy kiểm tra lại mã, hoặc nhờ người dẫn đọc bắt đầu lại","crLostT":"Mất kết nối — bạn có thể tham gia lại","crLibErr":"Không tải được thành phần Cùng đọc — hãy kiểm tra kết nối mạng","crSent":"Đã gửi cho người dẫn đọc","crAway":"người dẫn đọc đang ở trang khác","crGuest":"Bạn hữu","crLeader":"Người dẫn đọc","crCopied":"Đã sao chép liên kết","crNoShare":"Thiết bị này không hỗ trợ chia sẻ","crGuestTip":"Bạn có thể “Tự xem riêng” bất cứ lúc nào, rồi chạm “Quay lại với người dẫn đọc” để nhảy đến chỗ người dẫn đọc đang ở. Các câu bạn gạch dưới và trang đã đánh dấu chỉ nằm trên điện thoại của bạn.","crTip":"Khi mọi người đã tham gia, người dẫn đọc đi đến đâu — chương nào, vị trí cuộn nào, câu nào được chạm, đoạn nào đang đọc to — điện thoại của tất cả mọi người sẽ cùng theo, với ngôn ngữ và cỡ chữ riêng của mỗi người (người dẫn đọc dùng tiếng Trung phồn thể còn bạn dùng tiếng Anh vẫn thấy cùng một chương, một câu). Muốn chiếu lên TV, hãy dùng tính năng phản chiếu màn hình của điện thoại (AirPlay / Chromecast)."};
P.QBANK = ["Đoạn Kinh Thánh này cho tôi thấy Đức Chúa Trời là Đấng như thế nào?","Đoạn Kinh Thánh này phơi bày con người cũ vị kỷ nào trong tôi?","Nếu để Chúa Giê-xu làm Vua trong việc này, tôi sẽ làm gì?","Ở đây, Chúa Giê-xu cho tôi thấy tấm gương nào?","Hôm nay Đức Thánh Linh đang dẫn tôi bước một bước nào?","Vì sao những người trong đoạn này vấp ngã? Gốc rễ là kiêu ngạo hay sợ hãi?","Đoạn này giúp tôi thực hành lối sống từ bỏ cái tôi (Vô Kỷ) như thế nào?","Tôi nên đem đoạn Kinh Thánh này vào mối quan hệ nào của mình?","Đoạn này liên quan thế nào đến lời “Nước Cha được đến” trong bài cầu nguyện Chúa dạy?","Hãy cho tôi một hình ảnh đời thường để mở ra trọng tâm của đoạn này."];
P.QAUD = {"seeker":["Đoạn này liên quan gì đến cuộc sống hiện tại của tôi?","Tôi chưa phải là Cơ Đốc nhân. Lời này có ý nghĩa gì với tôi?","Có Đức Chúa Trời thật không? Có những lý do nào để tin?","Vì sao Kinh Thánh nói ai cũng cần Chúa Giê-xu?","Tôi đang chịu rất nhiều áp lực. Kinh Thánh giúp được gì thiết thực?","“Tội lỗi” ở đây nghĩa là gì? Có liên quan đến tôi không?","Cơ Đốc nhân hay nói về “ân điển”. Nói cho đơn giản thì nghĩa là gì?","Nếu muốn tìm hiểu thêm, tôi nên bắt đầu từ đâu?"],"teen":["Đoạn này liên quan thế nào đến cuộc sống hằng ngày của mình: trường lớp, bạn bè, điện thoại?","Nếu đoạn này là lời Đức Chúa Trời gửi riêng cho mình, thì Ngài đang nói gì?","Ai cũng làm vậy cả. Nếu mình không làm theo thì có kỳ cục không? Kinh Thánh nói gì?","Bạn có thể giải thích đoạn này bằng một trò chơi hoặc một bộ phim không?","Có điều gì bất ngờ hoặc ít người biết về đoạn này?","Áp lực thi cử lớn quá. Đoạn này cho mình sức mạnh nào?","Mình không thể tha thứ cho một người. Đoạn này giúp mình thế nào?","Đức Chúa Trời có thật sự nhìn thấy mình không? Điều gì khiến mình đáng được yêu thương?"],"kid":["Câu chuyện này kể về điều gì? Kể cho mình nghe nhé.","Trong câu chuyện này, Đức Chúa Trời đã làm gì?","Chúa Giê-xu có yêu mình không? Làm sao mình biết?","Trong câu chuyện này, ai là người can đảm nhất? Vì sao?","Làm sao mình có thể giống những người trong câu chuyện này?","Hãy dạy mình một câu Kinh Thánh ngắn để mình nhớ nhé.","Mình vừa cãi nhau với bạn thân. Chúa Giê-xu sẽ làm gì?","Bạn dạy mình một lời cầu nguyện nhỏ được không?"]};
P.AUD2 = {"elder":{"q":["Nói bằng lời đơn giản nhất, đoạn này đang nói điều gì?","Đoạn này an ủi những người lớn tuổi như thế nào?","Thân thể tôi ngày càng yếu đi. Đức Chúa Trời gìn giữ tôi ra sao?","Tôi thường thấy cô đơn. Đoạn này ban cho tôi điều gì?","Làm sao tôi có thể để lại đức tin cho con cháu?","Có những điều tôi vẫn chưa buông xuống được. Đoạn này dạy tôi phó thác như thế nào?","Tôi đã già rồi. Tôi còn có thể làm gì cho Đức Chúa Trời?","Xin viết giúp tôi một lời cầu nguyện ngắn để tôi đọc với Chúa."],"fu":["Sức khỏe","Cô đơn","Gia đình","Phó thác","Hy vọng","Cầu nguyện"],"rw":["Bạn đã đọc xong cả sách {nm}!","Ngày qua ngày, bạn đã đi được đến đây. Đức Chúa Trời nhớ đến sự trung tín này, và đó là tấm gương cho những người trẻ hơn như chúng ta."],"res":["Không sao đâu, cứ từ từ. Đọc thêm một lần nữa sẽ hiểu rõ hơn.","Hay quá! Bạn nhớ được nhiều điều trong chương này.","Tuyệt vời! Lời Chúa đang sống trong lòng bạn."]},"single_parent":{"q":["Tôi đang một mình nuôi con. Đoạn này an ủi tôi như thế nào?","Tôi mệt mỏi quá và cảm thấy mình mắc nợ các con. Đức Chúa Trời nhìn tôi ra sao?","Đức Chúa Trời chăm sóc người mồ côi và người góa bụa như thế nào, và điều đó có ý nghĩa gì với tôi?","Tiền bạc đang rất eo hẹp. Đoạn này ban cho tôi điều gì?","Con tôi cãi lại và cảm xúc rất mạnh. Tôi nên làm gì?","Tôi không biết nói với con thế nào về việc bố (hoặc mẹ) không có ở đây.","Tôi thật sự rất cô đơn. Làm sao tôi có thể xin Hội Thánh hoặc anh chị em giúp đỡ?","Xin viết cho tôi một lời cầu nguyện ngắn, chỉ năm phút là đọc xong."],"fu":["Mệt mỏi","Con cái","Tiền bạc","Nhờ giúp đỡ","Hy vọng","Cầu nguyện"],"rw":["Bạn đã đọc xong cả sách {nm}!","Giữ được thói quen đọc Kinh Thánh khi một mình gánh vác gia đình không hề dễ. Đức Chúa Trời thấy từng bước chân của bạn, và Ngài ở cùng bạn."],"res":["Không sao đâu, bạn đã cố gắng rất nhiều. Khi nào rảnh hãy đọc lại nhé.","Hay lắm! Bận rộn như vậy mà bạn vẫn nhớ được nhiều đến thế.","Tuyệt vời! Lời Chúa đang nâng đỡ bạn."]},"single":{"q":["Là người độc thân, đoạn này nói gì với tôi?","Tôi cảm thấy cô đơn. Đoạn này ban cho tôi điều gì?","Tôi là ai trong Đấng Christ, và giá trị của tôi là gì?","Làm sao tôi tin cậy Đức Chúa Trời trong lúc chờ đợi?","Kinh Thánh cho chúng ta sự khôn ngoan nào về các mối quan hệ?","Thời gian và sức lực của người độc thân có thể được dâng cho Đức Chúa Trời như thế nào?","Làm sao để xây dựng những mối quan hệ tốt trong Hội Thánh và với bạn bè?","Xin viết cho tôi một lời cầu nguyện ngắn dành cho người độc thân."],"fu":["Cô đơn","Căn tính","Chờ đợi","Các mối quan hệ","Mục đích sống","Cầu nguyện"],"rw":["Bạn đã đọc xong cả sách {nm}!","Bạn đã kiên trì bước đi một mình, và trước mặt Đức Chúa Trời, những ngày của bạn trọn vẹn và được yêu thương."],"res":["Không sao đâu, cứ từ từ. Đọc thêm một lần nữa sẽ rõ hơn.","Hay lắm! Bạn đã nắm được những ý chính của chương này.","Xuất sắc! Bạn thật chuyên cần, và Lời Chúa đang bén rễ trong bạn."]},"parent":{"q":["Đoạn này nhắc tôi điều gì với tư cách là cha mẹ?","Con tôi không chịu nghe lời và cảm xúc rất mạnh. Tôi nên phản ứng thế nào?","Làm sao cân bằng giữa kỷ luật và ân điển?","Làm sao để trò chuyện tốt với con tuổi thiếu niên?","Tôi hay nổi nóng với con rồi lại thấy day dứt. Giờ tôi nên làm gì?","Làm sao dẫn con biết Đức Chúa Trời, chứ không chỉ đi nhà thờ?","Vợ chồng tôi bất đồng về cách dạy con. Đoạn này nói gì?","Xin viết cho tôi một lời cầu nguyện chúc phước ngắn cho con."],"fu":["Trò chuyện","Kỷ luật","Day dứt","Vợ chồng","Đức tin","Cầu nguyện"],"rw":["Bạn đã đọc xong cả sách {nm}!","Giữa bao bộn bề nuôi dạy con cái mà ngày nào cũng đọc Kinh Thánh, đó là tấm gương tốt nhất bạn có thể dành cho con."],"res":["Không sao đâu, cứ từ từ. Khi nào có thể hãy đọc lại nhé.","Hay lắm! Bạn đã nắm được những ý chính của chương này.","Tuyệt vời! Lời Chúa đang bén rễ trong gia đình bạn."]},"couple":{"q":["Đoạn này nói gì với vợ chồng chúng tôi?","Sau mỗi lần cãi nhau, chúng tôi lại lạnh nhạt. Làm sao một người có thể chủ động làm hòa trước?","Làm sao tôi nói ra điều trong lòng để người bạn đời có thể lắng nghe?","Người bạn đời đã làm tôi tổn thương. Tôi có thật sự phải tha thứ không?","Chúng tôi bất đồng về tiền bạc và việc nhà. Phải làm sao?","Làm sao chúng tôi có thể cùng nhau cầu nguyện và đến gần Đức Chúa Trời?","Cuộc sống bận rộn khiến chúng tôi xa cách nhau. Làm sao để gần gũi trở lại?","Xin viết một lời cầu nguyện chúc phước ngắn cho hôn nhân của chúng tôi."],"fu":["Trò chuyện","Tha thứ","Gần gũi","Hiệp một","Cùng đọc","Cầu nguyện"],"rw":["Hai bạn đã cùng nhau đọc xong cả sách {nm}!","Đôi vợ chồng cùng nhau đến gần Lời Đức Chúa Trời là đứng trên nền vững chắc."],"res":["Không sao đâu, cứ thong thả. Một buổi tối nào đó, hai bạn hãy cùng đọc lại nhé.","Hay lắm! Hai bạn đã nắm được ý chính của chương này.","Tuyệt vời! Lời Đức Chúa Trời đang bén rễ trong hôn nhân của hai bạn."]},"pastor":{"q":["Đoạn này nói gì với tôi trong chức vụ?","Xin giúp tôi tìm dàn bài giảng và điểm vào đề cho đoạn này.","Tôi kiệt sức và gần như quá tải. Đoạn này an ủi tôi thế nào?","Làm sao tôi đối diện với lời chỉ trích và sự hiểu lầm trong Hội Thánh?","Đoạn này nói gì về việc dẫn dắt một nhóm hiệp một?","Giữa chức vụ bận rộn, làm sao tôi giữ gìn sự đồng đi của chính mình với Đức Chúa Trời?","Làm sao tôi chăn dắt người yếu đuối, người bị tổn thương và những người đã rời đi?","Xin viết một lời cầu thay ngắn cho Hội Thánh và các đồng sự của tôi."],"fu":["Bài giảng","Chăn bầy","Nhóm","Nghỉ ngơi","Chiến trận","Cầu thay"],"rw":["Bạn đã đọc xong cả sách {nm}!","Giữa chức vụ bận rộn mà vẫn ở gần Lời Đức Chúa Trời, đó là cội rễ sâu nhất của việc chăn bầy."],"res":["Không sao đâu, cứ thong thả. Khi nào có thể hãy đọc lại nhé.","Hay lắm! Bạn đã nắm được ý chính của chương này.","Tuyệt vời! Lời Đức Chúa Trời nuôi người chăn trước, rồi mới tuôn chảy đến bầy chiên."]}};
